    await test('旧日满理智也买完全部Buff及理智库存且不买装备技能', `fixture.dungeonShopScenario();fixture.goods.unshift({name:'理智水晶',price:10,remaining:5});fixture.goods.push({name:'生命祝福',price:20,remaining:3});fixture.shopMoney=1000;await h.handleShopNode({sanity:20});return fixture.bought.length===13&&fixture.goods[0].remaining===0&&fixture.goods[2].remaining===0&&fixture.goods[4].remaining===0&&!fixture.bought.includes('精钢剑')&&!fixture.bought.includes('技能书：进攻')&&h.runtime.shopSpent===510&&fixture.shopMoney===490`);
