    await test('地下城明确username允许同名队员精确关联', `fixture.hermitBattle();fixture.dungeon.members.forEach(m=>m.name='同名');fixture.battle.allies.forEach((a,i)=>{a.username=fixture.dungeon.members[i].key;a.entry.key='同名';a.battler.name='同名'});await h.setupBattleLineup('order','旧日',h.dungeonPolicy());return JSON.stringify(fixture.battle.allies_order)==='[3,1,2]'`);
    await test('地下城key和战斗名指向不同队员时停止', `fixture.hermitBattle();fixture.battle.allies[0].entry.key='ldya';await h.runTask('冲突',()=>h.setupBattleLineup('order','旧日',h.dungeonPolicy()));return h.runtime.outcome==='error'&&!fixture.calls.some(r=>r.path.endsWith('/swap'))`);
    await test('地下城刷新期间换局不套用旧队伍排序', `fixture.hermitBattle();const old=h.dungeonPolicy();fixture.dungeon={...fixture.dungeon,dungeon_id:'another'};await h.runTask('换局',()=>h.setupBattleLineup('order','旧日',old));return h.runtime.outcome==='error'&&!fixture.calls.some(r=>r.path.endsWith('/swap'))`);
